'use strict';
const BANK=window.CHEM_BANK;
// Adaptació del banc al temari i a la nomenclatura catalana demanats.
const NONMETALS=new Set(['B','C','N','P','S','F','Cl','Br','I','Se','Te','Si','As','Sb']);
for(const c of BANK){
  if(c.g==='ox' && Object.keys(c.ox).some(e=>e!=='O' && NONMETALS.has(e))){c.g='oxnm';}
  if(c.g==='hn'){
    const gasNames={HCl:"clorur d'hidrogen",HF:"fluorur d'hidrogen",HBr:"bromur d'hidrogen",HI:"iodur d'hidrogen",H2S:"sulfur de dihidrogen",H2Se:"seleniur de dihidrogen",H2Te:"tel·lurur de dihidrogen"};
    const commonHydrides={SiH4:'silà',CH4:'metà',NH3:'amoníac',PH3:'fosfà',AsH3:'arsà',SbH3:'estibà'};
    if(gasNames[c.f]){c.g='sb';c.n={stock:[gasNames[c.f]]};c.note='Compost d’hidrogen i un no-metall. En dissolució aquosa, el nom canvia a àcid hidràcid.';}
    else if(commonHydrides[c.f]){c.g='hn';c.n={common:[commonHydrides[c.f]]};c.note='Hidrur no metàl·lic: utilitza el nom habitual treballat a classe.';}
    else c.g='hidden';
  }
  if(c.g==='op') c.g='hidden';
  // Els ions es mantenen al banc i es poden practicar en el seu apartat.
  if(c.g==='oxnm'){
    const systematic={'CO':'monòxid de carboni','CO2':'diòxid de carboni','SO2':'diòxid de sofre','SO3':'triòxid de sofre','N2O3':'triòxid de dinitrogen','N2O5':'pentaòxid de dinitrogen','Cl2O7':'heptaòxid de diclor'};
    if(systematic[c.f]) c.n.pref=[systematic[c.f]];
  }
  if(c.g==='oa'){
    const acids={HClO:'àcid hipoclorós',HClO2:'àcid clorós',HClO3:'àcid clòric',HClO4:'àcid perclòric',H2SO3:'àcid sulfurós',H2SO4:'àcid sulfúric',HNO2:'àcid nitrós',HNO3:'àcid nítric',H2CO3:'àcid carbònic',H2CrO4:'àcid cròmic',H2Cr2O7:'àcid dicròmic',H2MnO4:'àcid mangànic',HMnO4:'àcid permangànic',H2SO2:'àcid hiposulfurós',HBrO:'àcid hipobromós',HBrO2:'àcid bromós',HBrO3:'àcid bròmic',HBrO4:'àcid perbròmic',HIO:'àcid hipoiodós',HIO2:'àcid iodós',HIO3:'àcid iòdic',HIO4:'àcid periòdic',H2SeO3:'àcid seleniós',H2SeO4:'àcid selènic',H2TeO3:'àcid tel·lurós',H2TeO4:'àcid tel·lúric',H3PO4:'àcid fosfòric',H3PO3:'àcid fosforós',H3BO3:'àcid bòric',H3AsO4:'àcid arsènic',H3SbO4:'àcid ortoantimònic'};
    if(acids[c.f]) c.n.trad=[acids[c.f]];
  }
  if(c.g==='sn'){
    if(c.n.trad) c.n.trad=c.n.trad.map(n=>n.replace(/ato\b/g,'at').replace(/ito\b/g,'it'));
  }
  if(['ox','pe','hm','oh','sb'].includes(c.g)){
    if(c.n.stock) c.n.stock=c.n.stock.map(n=>n.replace(/de argent/g,"d'argent").replace(/de alumini/g,"d'alumini").replace(/de estany/g,"d'estany").replace(/de antimoni/g,"d'antimoni"));
  }
  if(c.g==='ah'){
    const hydra={'HCl':'àcid clorhídric','HF':'àcid fluorhídric','HBr':'àcid bromhídric','HI':'àcid iodhídric','H2S':'àcid sulfhídric','H2Se':'àcid selenhídric','H2Te':'àcid tel·lurhídric'};
    c.n.trad=[hydra[c.f]];
  }
}
const silane=BANK.find(c=>c.f==='SiH4');
if(silane){silane.g='hn';silane.n={common:['silà']};silane.ox={Si:-4,H:1};silane.note='En el silà, el silici treballa amb −4 i l’hidrogen amb +1.';}

// Els cianurs formen part de les sals binàries; CN− es tracta com un grup.
const cyanides=[
 {f:'NaCN',name:'cianur de sodi',ox:{Na:1,C:2,N:-3}},
 {f:'KCN',name:'cianur de potassi',ox:{K:1,C:2,N:-3}},
 {f:'Ca(CN)2',name:'cianur de calci',ox:{Ca:2,C:2,N:-3}},
 {f:'AgCN',name:'cianur d’argent',ox:{Ag:1,C:2,N:-3}},
 {f:'Fe(CN)2',name:'cianur de ferro(II)',ox:{Fe:2,C:2,N:-3}},
 {f:'Fe(CN)3',name:'cianur de ferro(III)',ox:{Fe:3,C:2,N:-3}}
];
for(const x of cyanides) BANK.push({id:BANK.length,f:x.f,g:'sb',n:{stock:[x.name]},ox:x.ox,level:1,charge:0,note:'El grup cianur CN− té càrrega −1 i es manté unit en formular el compost.',units:null});
BANK.push({id:BANK.length,f:'C4H10',g:'hn',n:{common:['butà']},ox:{C:-2.5,H:1},level:0,charge:0,note:'El valor −2,5 és l’estat d’oxidació mitjà del carboni en el butà.',units:null});
const aqueousAcids=[['HCl','àcid clorhídric'],['HF','àcid fluorhídric'],['HBr','àcid bromhídric'],['HI','àcid iodhídric'],['H2S','àcid sulfhídric'],['H2Se','àcid selenhídric'],['H2Te','àcid tel·lurhídric']];
for(const [base,name] of aqueousAcids){const source=BANK.find(c=>c.f===base&&c.g==='sb');if(source)BANK.push({id:BANK.length,f:base+'(aq)',g:'ah',n:{trad:[name]},ox:{...source.ox},level:0,charge:0,note:'(aq) indica que el compost està dissolt en aigua i el diferencia del compost d’hidrogen sense aquesta indicació.',units:null});}
BANK.push({id:BANK.length,f:'NO',g:'oxnm',n:{pref:['monòxid de nitrogen']},ox:{N:2,O:-2},level:1,charge:0,note:'En aquest òxid, el nitrogen treballa amb +2 i l’oxigen amb −2.',units:null});
BANK.push({id:BANK.length,f:'NO2',g:'oxnm',n:{pref:['diòxid de nitrogen']},ox:{N:4,O:-2},level:1,charge:0,note:'En aquest òxid, el nitrogen treballa amb +4 i l’oxigen amb −2.',units:null});
for(const c of BANK) if(c.f==='NH4^+') c.n={trad:['ió amoni']};
BANK.push({id:BANK.length,f:'CN^-',g:'io',n:{trad:['ió cianur']},ox:{C:2,N:-3},level:0,charge:-1,note:'El grup cianur és CN⁻ i té càrrega −1.',units:null});
BANK.push({id:BANK.length,f:'SeO4^2-',g:'io',n:{trad:['ió selenat']},ox:{Se:6,O:-2},level:0,charge:-2,note:'L’ió selenat és SeO₄²⁻.',units:null});
BANK.push({id:BANK.length,f:'NH4Cl',g:'sb',n:{stock:['clorur d’amoni']},ox:{N:-3,H:1,Cl:-1},level:1,charge:0,note:'El catió amoni NH₄⁺ té càrrega +1 i el clorur Cl⁻ té càrrega −1.',units:null});
BANK.push({id:BANK.length,f:'Ti(CN)4',g:'sb',n:{stock:['cianur de titani']},ox:{Ti:4,C:2,N:-3},level:1,charge:0,note:'El titani treballa amb +4 i cada grup cianur CN⁻ té càrrega −1. Mantén els quatre grups CN entre parèntesis.',units:null});


const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const GROUPS=[['home','Inici','🏠'],['cheat','Guia ràpida','📋'],['ox','Òxids metàl·lics · Stock','🫧'],['oxnm','Òxids de no-metalls · sistemàtica','⚗️'],['hm','Hidrurs metàl·lics · Stock','🔩'],['hn','Hidrurs no metàl·lics','🫧'],['oh','Hidròxids · Stock','💧'],['pe','Peròxids · Stock','✨'],['sb','Sals binàries · Stock','🧂'],['ah','Àcids hidràcids','🧪'],['sn','Oxosals','⚖️'],['sa','Sals àcides','🧂'],['oa','Oxoàcids','🍋'],['io','Ions','⚡'],['practice','Practica','🎯'],['teacher','Professorat 🔒','🗝️']];
const CHEM=GROUPS.filter(g=>['ox','oxnm','hm','hn','oh','pe','sb','ah','sn','sa','oa','io'].includes(g[0])),COLORS=['var(--violet)','var(--pink)','var(--orange)','var(--blue)'];
const NOM={pref:'Sistemàtica amb prefixos',stock:'Nomenclatura Stock',charge:'Nombre de càrrega',trad:'Nom tradicional',hyd:'Nomenclatura amb hidrogen',subst:'Substitutiva',common:'Nom habitual'};
function methodFor(c){if(c.g==='hn')return 'common';if(c.g==='io')return c.n.trad?'trad':(c.n.stock?'stock':'pref');return c.g==='oxnm'?'pref':(['ah','sn','sa','oa'].includes(c.g)?'trad':'stock')}
let storageOK=true;function read(k,fallback){try{let x=localStorage.getItem('leirelab.'+k);if(x===null){x=localStorage.getItem('inorgalab.'+k);if(x!==null)localStorage.setItem('leirelab.'+k,x)}return x===null?fallback:JSON.parse(x)}catch(e){storageOK=false;return fallback}}function save(k,v){try{localStorage.setItem('leirelab.'+k,JSON.stringify(v));return true}catch(e){storageOK=false;return false}}
let progress=read('progress',{total:0,right:0,stars:0,errors:[],groups:{}}), prefs=read('prefs',{dark:false,reduce:false,mode:'light'});
if(!progress||!Array.isArray(progress.errors)||!progress.groups)progress={total:0,right:0,stars:0,errors:[],groups:{}};
if(!prefs||typeof prefs!=='object')prefs={dark:false,reduce:false,mode:'light'};
if(!prefs.mode)prefs.mode=prefs.dark?'dark':'light';
let tab='home',unlocked=false;try{unlocked=(sessionStorage.getItem('leirelab.teacher')||sessionStorage.getItem('inorgalab.teacher'))==='4545'}catch(e){}
let session=null,collection=null,superMode=false,reviewMode=false;
function applyPrefs(){const mode=prefs.mode||'light';document.body.classList.toggle('dark',mode==='dark');document.body.classList.toggle('fashion',mode==='fashion');document.body.classList.toggle('reduce',prefs.reduce);$('theme').textContent=mode==='fashion'?'🌸 Mode Fashion':mode==='dark'?'☾ Mode fosc':'☀ Mode clar';$('theme').setAttribute('aria-label','Canvia el tema visual; tema actual: '+(mode==='fashion'?'Fashion':mode==='dark'?'fosc':'clar'));$('reduce').checked=prefs.reduce}
$('theme').onclick=()=>{const modes=['light','dark','fashion'];prefs.mode=modes[(modes.indexOf(prefs.mode)+1)%modes.length];prefs.dark=prefs.mode==='dark';save('prefs',prefs);applyPrefs()};$('reduce').onchange=e=>{prefs.reduce=e.target.checked;save('prefs',prefs);applyPrefs()};applyPrefs();
const subdigits='₀₁₂₃₄₅₆₇₈₉',supdigits='⁰¹²³⁴⁵⁶⁷⁸⁹';
function pretty(f){let [body,charge]=f.split('^');body=body.replace(/\d/g,d=>subdigits[d]);return body+(charge?charge.replace(/\d/g,d=>supdigits[d]).replaceAll('+','⁺').replaceAll('-','⁻'):'')}
function form(f){return '<span class="formula">'+esc(pretty(f))+'</span>'}
function mascot(kind=0,color='var(--violet)'){
 const bodies=[`<path d="M44 10h32v9h-5v31l31 57q4 9-8 9H26q-12 0-8-9l31-57V19h-5z"/><path d="M30 88h60l10 20q2 5-7 5H27q-8 0-5-5z" fill="${color}"/>`,`<path d="M40 12h40v9h-5v75q0 21-15 21T45 96V21h-5z"/><path d="M48 65h24v31q0 18-12 18T48 96z" fill="${color}"/>`,`<path d="M28 30h66l-7 9v65q0 12-12 12H38q-10 0-10-12z"/><path d="M31 79h53v25q0 9-10 9H40q-9 0-9-9z" fill="${color}"/><path d="M33 48h15m-15 12h10m-10 12h15" fill="none"/>`,`<path d="M51 10h18v45q28 12 28 34 0 27-37 27T23 89q0-22 28-34z"/><path d="M28 84h64q8 29-32 29T28 84z" fill="${color}"/>`,`<path d="M51 10h18v76H51zM43 86h34v14H43zM27 112h66l-16-12H43z"/><path d="M54 40h12v43H54z" fill="${color}"/>`,`<path d="M12 56l15-12 64 11 15 12-17 11-65-11z"/><path d="M31 48l56 10-2 15-56-9z" fill="${color}"/>`,`<path d="M46 42h28v57H46zM30 100h60v16H30z"/><path d="M60 39q-23-12 1-35 23 24-1 35z" fill="${color}"/>`,`<circle cx="60" cy="64" r="36"/><ellipse cx="60" cy="64" rx="55" ry="18" fill="none" transform="rotate(35 60 64)"/><ellipse cx="60" cy="64" rx="55" ry="18" fill="none" transform="rotate(-35 60 64)"/><circle cx="60" cy="64" r="30" fill="${color}"/>`];
 return `<svg class="mascot" viewBox="0 0 120 135" role="img" aria-label="${kind===0?'Leire, el teu matràs tutor':'Personatge de laboratori'}"><g fill="var(--panel)" stroke="var(--ink)" stroke-width="3" stroke-linejoin="round">${bodies[kind%8]}</g><g class="eye"><ellipse cx="48" cy="65" rx="10" ry="13" fill="white" stroke="var(--ink)" stroke-width="2"/><ellipse cx="73" cy="65" rx="10" ry="13" fill="white" stroke="var(--ink)" stroke-width="2"/><g fill="#28203e"><circle class="pupil" cx="49" cy="67" r="4"/><circle class="pupil" cx="74" cy="67" r="4"/></g><path d="M40 52l-4-7m11 7-1-9m26 9 1-9m7 10 5-7" stroke="${color}" stroke-width="3"/></g><path class="mouth" d="M48 80q12 15 25 0"/><path class="tear" d="M87 75q-9 13 0 13t0-13" fill="var(--blue)"/><path d="M32 116l-5 12m60-12 6 12" stroke="var(--ink)" stroke-width="3"/></svg>`
}
let eyeTime=0;document.addEventListener('pointermove',e=>{if(prefs.reduce||matchMedia('(prefers-reduced-motion: reduce)').matches||Date.now()-eyeTime<45)return;eyeTime=Date.now();document.querySelectorAll('.mascot').forEach(svg=>{const r=svg.getBoundingClientRect();const dx=Math.max(-3,Math.min(3,(e.clientX-r.x-r.width/2)/60)),dy=Math.max(-2,Math.min(2,(e.clientY-r.y-r.height/2)/80));svg.querySelectorAll('.pupil').forEach(p=>p.style.transform=`translate(${dx}px,${dy}px)`)});},{passive:true});
function nav(){ $('nav').innerHTML=GROUPS.map((g,i)=>`<button style="--accent:${COLORS[i%4]}" class="${g[0]===tab?'active':''}" aria-current="${g[0]===tab?'page':'false'}" onclick="go('${g[0]}')"><span aria-hidden="true">${i>=2&&i<=12?mascot((i-2)%8,COLORS[i%4]):g[2]}</span>${g[1]}</button>`).join('')}
function go(id,focus=true){tab=id;nav();if(id==='home')home();else if(id==='cheat')cheat();else if(id==='practice')practice();else if(id==='teacher')teacher();else theory(id);if(focus){$('main').focus();window.scrollTo({top:0,behavior:'instant'})}}
const title=id=>GROUPS.find(g=>g[0]===id)?.[1]||id;
function foot(){return `<footer>LeireLab · 3r–4t d’ESO i 1r de batxillerat · El progrés es desa en aquest navegador. ${!storageOK?'L’emmagatzematge no està disponible: pots continuar sense desar.':''}<br>Referència: <a href="https://iupac.org/what-we-do/nomenclature/brief-guides/" target="_blank" rel="noopener">Guies de nomenclatura de la IUPAC</a>. A cada grup s’indiquen les convencions escolars.</footer>`}
function home(){ $('main').innerHTML=`<div class="hero"><div><div class="eyebrow">El teu laboratori de formulació</div><h1>Quin nom<br>té aquesta fórmula?</h1><p>Sóc la <strong>Leire</strong>. Unirem càrregues, desxifrarem noms i entrenarem la química. Pas a pas i sense por d’equivocar-te.</p><div class="row"><button class="primary" onclick="go('practice')">🎯 A practicar!</button><button onclick="go('cheat')">Consulta la guia ràpida</button></div><p class="notice">${BANK.length} compostos · ${CHEM.length} famílies · Dues direccions: anomenar i formular</p></div><div class="hero-art">${mascot(0)}<span class="atom">Na</span><span class="atom">O</span></div></div><div class="stats"><div class="stat">⭐ <b>${progress.stars}</b> estrelles</div><div class="stat">🎯 <b>${progress.right}/${progress.total}</b> encerts</div><div class="stat">🧠 <b>${progress.errors.length}</b> per repassar</div></div><h2>Tria el teu pròxim descobriment</h2><div class="grid">${CHEM.map((g,i)=>`<button class="card group-card" style="--accent:${COLORS[i%4]}" onclick="go('${g[0]}')">${mascot(i%8,COLORS[i%4])}<span class="tag">${i+1<10?'0':''}${i+1}</span><strong>${g[1]}</strong><small>${BANK.filter(c=>c.g===g[0]).length} compostos · teoria i reptes</small></button>`).join('')}</div>${foot()}`}
function cheat(){ $('main').innerHTML=`<div class="lab-head">${mascot(2)}<div><div class="eyebrow">Sempre a mà</div><h1>La guia ràpida de la Leire</h1><p>La valència de combinació i l’estat d’oxidació no sempre són el mateix.</p></div></div><div class="grid"><section class="card"><h2>Metalls: valències del curs</h2>${table(['Elements','Valències'],[['Li, Na, K, Rb, Cs, Fr, Ag','+1'],['Mg, Ca, Sr, Ba, Zn, Cd, Ra','+2'],['Al, Sc','+3'],['V','+2, +3, +4, +5'],['Ti','+4'],['Pd, Pt','+2, +4'],['Co, Ni','+2, +3'],['Hg','+1, +2'],['Au','+1, +3'],['Ge','+2, +4'],['Bi','+3, +5'],['Fe','+2, +3'],['Cu','+1, +2'],['Sn, Pb','+2, +4'],['Cr','+2, +3, +6'],['Mn','+2, +3, +4, +6, +7']])}<p class="notice">El mercuri(I) forma el catió Hg₂²⁺. Per això, en formular-lo, cal mantenir el grup Hg₂.</p></section><section class="card"><h2>No-metalls</h2>${table(['Elements','Estats habituals'],[['F','−1'],['Cl, Br, I','−1 en sals; +1, +3, +5, +7 en oxoàcids'],['O','−2; −1 en peròxids'],['S, Se, Te','−2; +4 i +6 en oxoàcids'],['N','+2 i +4 en òxids; +1, +3 i +5 en la resta de compostos treballats'],['P, As, Sb','−3 en hidrurs; +3 i +5 en oxoàcids'],['C, Si','+4 en els compostos treballats'],['B','+3'],['H','−1 en hidrurs metàl·lics; +1 en àcids']])}</section><section class="card"><h2>Prefixos</h2>${table(['Quantitat','Prefix'],[['1','mono-'],['2','di-'],['3','tri-'],['4','tetra-'],['5','penta-'],['6','hexa-'],['7','hepta-'],['8','octa-'],['9','nona-'],['10','deca-']])}<p>Exemples: CO, monòxid de carboni; N₂O₅, pentaòxid de dinitrogen.</p></section><section class="card"><h2>Estats romans i càrregues</h2><p>I = 1 · II = 2 · III = 3 · IV = 4 · V = 5 · VI = 6 · VII = 7.</p><p><b>Ferro(III)</b> indica l’estat d’oxidació. <b>Ferro(3+)</b> indica el nombre de càrrega d’un catió.</p><p>Si un metall només té una valència, no cal escriure el nombre romà: òxid de sodi.</p><h3>Nomenclatura tradicional</h3><p>En alguns oxoàcids: hipo-…-ós → …-ós → …-ic → per-…-ic.</p><p>En les sals: −ós → −it; −ic → −at.</p></section></div><div class="callout">Intercanvia les càrregues per obtenir la proporció mínima. No separis els grups O₂²⁻, OH⁻ ni els oxoanions.</div>${foot()}`}
function table(head,rows){return `<div class="table-scroll"><table><thead><tr>${head.map(h=>'<th scope="col">'+h+'</th>').join('')}</tr></thead><tbody>${rows.map(row=>'<tr>'+row.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`}
const THEORY={
ox:{what:'Combinacions de l’oxigen amb un altre element. En aquests òxids, l’oxigen treballa amb −2.',example:'Fe2O3',steps:['El ferro(III) treballa amb +3 i l’oxigen amb −2.','Intercanvia els valors absoluts: Fe₂O₃.','2 × (+3) + 3 × (−2) = 0. No hi ha cap divisor comú.'],cross:['Fe³⁺','O²⁻','Fe₂O₃'],rules:{pref:'Compta els àtoms: triòxid de diferro. El prefix mono- se sol ometre, però CO és monòxid de carboni.',stock:'Òxid de + element (estat romà). No cal indicar l’estat si l’element només en té un.',charge:'Òxid de + metall (càrrega amb xifres aràbigues i signe). Només en el cas iònic de metalls amb diverses valències.'},warn:'No indiquis el nombre de càrrega a CO₂ ni als altres òxids covalents. FeO i Fe₂O₃ corresponen a estats diferents.'},
pe:{what:'Compostos amb el grup peròxid O₂²⁻: cada oxigen treballa amb estat d’oxidació −1.',example:'Na2O2',steps:['El sodi és Na⁺; el grup complet és O₂²⁻.','Calen dos Na⁺ per compensar una unitat O₂²⁻.','Escriu Na₂O₂ i conserva el grup O–O: no és NaO.'],cross:['2 Na⁺','O₂²⁻','Na₂O₂'],rules:{pref:'Compta tots els àtoms: diòxid de disodi.',stock:'Peròxid de + element. Indica l’estat romà si l’element té diverses valències: peròxid de coure(II).'},warn:'No simplifiquis la fórmula si això fa perdre el grup O₂. A CuO₂, el coure treballa amb +2, no pas amb +4.'},
hm:{what:'Compostos formats per un metall i hidrogen. En els hidrurs metàl·lics, l’hidrogen treballa amb −1.',example:'FeH3',steps:['Fe³⁺ i H⁻: identifica les càrregues.','Intercanvia els valors: Fe₁H₃.','Omet el subíndex 1: FeH₃. +3 + 3 × (−1) = 0.'],cross:['Fe³⁺','H⁻','FeH₃'],rules:{pref:'Prefix + hidrur de + metall: trihidrur de ferro.',stock:'Hidrur de + metall (estat romà quan calgui).',charge:'Hidrur de + metall (càrrega), si és iònic i té diverses valències.'},warn:'En els hidrurs metàl·lics, l’H treballa amb −1. No els confonguis amb HCl, on l’H treballa amb +1.'},
sb:{what:'Compostos binaris formats per dos elements diferents de l’oxigen i sense l’hidrogen propi dels hidrurs: metall + no-metall, o dos no-metalls.',example:'FeCl3',steps:['El ferro treballa amb +3; el clor, que és més electronegatiu, amb −1.','Intercanvia els valors: Fe₁Cl₃.','Escriu FeCl₃. En PCl₃, el fòsfor treballa amb +3, però el compost és covalent.'],cross:['Fe³⁺','Cl⁻','FeCl₃'],rules:{pref:'Prefix + nom del no-metall acabat en −ur + de + element.',stock:'Nom del no-metall acabat en −ur + de + element (estat romà si escau).',charge:'Només en sals iòniques amb metalls de valència variable: clorur de ferro(3+).'},warn:'L’element més electronegatiu té estat d’oxidació negatiu: Cl −1, F −1, S −2. L’altre pot ser un no-metall positiu; no li atribueixis una càrrega iònica real.'},
oh:{what:'Compostos iònics formats per un metall i el grup hidròxid OH⁻.',example:'Fe(OH)3',steps:['El catió és Fe³⁺ i cada OH⁻ aporta −1.','Necessites tres grups OH⁻. Mantén el grup unit.','Escriu Fe(OH)₃. +3 + 3 × (−1) = 0.'],cross:['Fe³⁺','OH⁻','Fe(OH)₃'],rules:{pref:'Prefix + hidròxid de + metall: trihidròxid de ferro.',stock:'Hidròxid de + metall (estat romà).',charge:'Hidròxid de + metall (càrrega), si té diverses valències.'},warn:'Amb més d’un grup OH, utilitza parèntesis: Ca(OH)₂. CaOH₂ indicaria una composició diferent. Amb un sol grup: NaOH.'},
oa:{what:'Àcids formats per hidrogen, oxigen i un element central. Habitualment, H treballa amb +1 i O amb −2.',example:'H2SO4',steps:['L’anió sulfat és SO₄²⁻: el sofre treballa amb +6 i els quatre oxígens amb −2.','Compensa la càrrega −2 amb dos H⁺: H₂SO₄.','També es pot representar formalment SO₃ + H₂O → H₂SO₄. És un esquema de formulació.'],cross:['2 H⁺','SO₄²⁻','H₂SO₄'],rules:{trad:'Ordena els estats d’oxidació: hipo-…-ós, …-ós, …-ic, per-…-ic. Per exemple, el clor pot treballar amb +1, +3, +5 o +7.',hyd:'Prefix d’H + nom de l’oxoanió. A classe, prioritza els noms tradicionals dels oxoàcids.'},warn:'No dedueixis el nom només comptant els H. Calcula l’estat d’oxidació de l’element central. Per exemple, a HClO₄, el clor treballa amb +7.'},
sn:{what:'Sals en què tots els hidrògens àcids d’un oxoàcid han estat substituïts per cations.',example:'Al2(SO4)3',steps:['Al³⁺ i SO₄²⁻: considera el grup com una unitat.','Intercanvia les càrregues: dos Al i tres grups sulfat.','Al₂(SO₄)₃. 2 × (+3) + 3 × (−2) = 0.'],cross:['Al³⁺','SO₄²⁻','Al₂(SO₄)₃'],rules:{trad:'Àcid acabat en −ós → sal acabada en −it; àcid acabat en −ic → sal acabada en −at. Conserva hipo- i per-.',pref:'Nom de l’oxoanió amb prefixos. Bis-, tris-… per als grups complexos repetits.'},warn:'Els parèntesis envolten l’anió complet quan es repeteix. Fe₂(SO₃)₃ és sulfit, no sulfat. Ca₃(PO₄)₂ manté PO₄ intacte.',extra:'<p>El dicromat és l’ió Cr₂O₇²⁻. Exemples: K₂Cr₂O₇, dicromat de potassi, i Na₂Cr₂O₇, dicromat de sodi.</p>'},
sa:{what:'Sals d’oxoàcids en què un o més hidrògens àcids es mantenen a l’oxoanió.',example:'Ca(HCO3)2',steps:['H₂CO₃ − H⁺ → HCO₃⁻: queda un hidrogen a l’anió.','Ca²⁺ necessita dos ions HCO₃⁻.','Escriu Ca(HCO₃)₂. Mantén HCO₃ com una unitat.'],cross:['Ca²⁺','HCO₃⁻','Ca(HCO₃)₂'],rules:{trad:'Hidrogeno- o dihidrogeno- + nom de l’anió. Si es repeteix, es pot fer servir bis(hidrogencarbonat).',pref:'Conserva l’H al grup: bis[hidrogen(trioxidocarbonat)] de calci.'},warn:'No confonguis NaHSO₄ amb Na₂SO₄. Aquí només s’inclouen sals àcides d’oxoàcids. La càrrega residual es calcula després de treure cada H⁺.',extra:'<p>H₃PO₄ − H⁺ → H₂PO₄⁻; H₃PO₄ − 2 H⁺ → HPO₄²⁻. La càrrega i el nombre d’hidrogens restants canvien alhora.</p>'}
};
THEORY.oxnm={what:'Òxids formats per oxigen i un no-metall. Es nomenen amb la nomenclatura sistemàtica i prefixos multiplicadors.',example:'SO3',steps:['Compta els àtoms de cada element a la fórmula.','Indica el nombre d’àtoms d’oxigen amb mono-, di-, tri-, penta-, hepta-…','Afegeix «d’» i el nom del no-metall amb el prefix que indiqui la seva quantitat.'],cross:['SO₃','triòxid','de sofre'],rules:{pref:'Nomenclatura sistemàtica: prefix + òxid de + prefix + no-metall. El prefix mono- s’utilitza quan cal distingir la proporció, com a monòxid de carboni.'},warn:'No utilitzis la nomenclatura Stock en aquest apartat: els òxids de no-metalls es treballen amb prefixos sistemàtics.'};
THEORY.ah={what:'Compostos binaris d’hidrogen amb un no-metall. Només quan són en dissolució aquosa s’anomenen àcids hidràcids.',example:'HCl(aq)',steps:['Sense indicar dissolució: HCl és clorur d’hidrogen.','En dissolució aquosa, s’escriu HCl(aq).','Només amb (aq) s’anomena àcid clorhídric.'],cross:['H⁺','Cl⁻','HCl(aq)'],rules:{trad:'HCl(aq): àcid clorhídric; HF(aq): àcid fluorhídric; HBr(aq): àcid bromhídric; HI(aq): àcid iodhídric; H₂S(aq): àcid sulfhídric.'},warn:'No confonguis HCl, clorur d’hidrogen, amb HCl(aq), àcid clorhídric.'};
THEORY.hn={what:'Hidrurs formats per hidrogen i un no-metall. En aquest apartat fem servir els noms habituals treballats a classe.',example:'SiH4',steps:['Identifica la fórmula de l’hidrur no metàl·lic.','Recorda el nom habitual: silà, metà, butà, amoníac, fosfà, arsà o estibà.','Escriu el nom sense afegir-hi prefixos que no treballeu a classe.'],cross:['Si','H','SiH₄'],rules:{common:'SiH₄: silà; CH₄: metà; C₄H₁₀: butà; NH₃: amoníac; PH₃: fosfà; AsH₃: arsà; SbH₃: estibà.'},warn:'No confonguis aquests hidrurs amb els hidrurs metàl·lics: en aquests últims, l’hidrogen treballa amb −1.'};
THEORY.io={what:'Els ions són àtoms o grups d’àtoms que tenen càrrega elèctrica.',example:'SeO4^2-',steps:['Compta els àtoms del grup i identifica la càrrega.','Escriu la càrrega com a superíndex, després de la fórmula.','CN⁻ és cianur, NH₄⁺ és amoni i SeO₄²⁻ és selenat.'],cross:['SeO₄','2−','SeO₄²⁻'],rules:{trad:'CN⁻: ió cianur; NH₄⁺: ió amoni; SeO₄²⁻: ió selenat. També practiquem clorur, sulfat, nitrat i carbonat.'},warn:'La càrrega de l’ió no és un subíndex. Escriu-la en superíndex: SeO₄²⁻.'};
function theory(g){const t=THEORY[g],index=CHEM.findIndex(x=>x[0]===g),list=BANK.filter(c=>c.g===g),ex=list.find(c=>c.f===t.example)||list[0];$('main').innerHTML=`<div class="lab-head">${mascot(index%8,COLORS[index%4])}<div><div class="eyebrow">Família ${index+1} · aprèn i prova</div><h1>${title(g)}</h1><p>${t.what}</p></div></div><section class="card"><h2>1. Què són?</h2><p>${t.what}</p>${t.extra||''}</section><section class="card"><h2>2. Com es formulen</h2>${t.steps.map((s,i)=>`<div class="step"><b class="num">${i+1}</b><div>${s}</div></div>`).join('')}<div class="cross" id="cross">${crossDiagram(g,false)}</div><button class="small" onclick="animateCross()">↗ ${CROSS_PAIRS[g]?"consulta el cruce de valències":"consulta los passos de composición"}</button><p class="notice">Exemple resolt: ${form(ex.f)} · ${esc(ex.note)}</p></section><h2>3. Com s’anomenen</h2><div class="grid">${Object.entries(t.rules).map(([k,rule])=>{let items=list.filter(c=>c.n[k]);let selected=[...(ex.n[k]?[ex]:[]),...items.filter(c=>c.id!==ex.id)].slice(0,3);return `<section class="card"><span class="tag">${NOM[k]}</span><p>${rule}</p>${selected.map(c=>`<p>${form(c.f)} → <b>${esc(c.n[k][0])}</b></p>`).join('')}</section>`}).join('')}</div><section class="card"><h2>4. Exemples</h2><p class="notice">Las columnas comparan las nomenclaturas del mismo compost. «—» indica que no se aplica en aquest banco.</p>${table(['fórmula',...Object.keys(t.rules).map(k=>NOM[k]),'pista de composición'],list.map(c=>[form(c.f),...Object.keys(t.rules).map(k=>c.n[k]?c.n[k].map(esc).join(' / '):'—'),esc(c.note)]))}</section><aside class="callout"><h2>5. Compte amb…</h2>${t.warn}</aside><button class="primary" onclick="practiceGroup('${g}')">🎯 Practica aquesta família</button>${foot()}`}
const CROSS_PAIRS={
ox:['Fe','O',3,2,'Fe₂O₃'], pe:['Na','O₂',1,2,'Na₂O₂'],
hm:['Fe','H',3,1,'FeH₃'], hn:['N','H',3,1,'NH₃'],
sb:['Fe','Cl',3,1,'FeCl₃'], oh:['Fe','OH',3,1,'Fe(OH)₃'],
oa:['H','SO₄',1,2,'H₂SO₄'], sn:['Al','SO₄',3,2,'Al₂(SO₄)₃'],
sa:['Ca','HCO₃',2,1,'Ca(HCO₃)₂']
};
function crossDiagram(g,play){
 const pair=CROSS_PAIRS[g], t=THEORY[g];
 if(!pair)return `<div>${t.cross[0]} + ${t.cross[1]} → ${t.cross[2]}</div><p class="notice">${t.steps.join(' → ')}</p>`;
 const [a,b,ca,cb,result]=pair, reduced=prefs.reduce||matchMedia('(prefers-reduced-motion: reduce)').matches;
 const moving=play&&!reduced;
 const an=(attr,values,dur='2s',begin='0.7s')=>moving?`<animate attributeName="${attr}" values="${values}" dur="${dur}" begin="${begin}" fill="freeze"/>`:'';
 const group=(x,n)=>n>1&&['OH','SO₄','HCO₃','O₂'].includes(x)?'('+x+')':x;
 const width=x=>[...x].reduce((n,c)=>n+('₀₁₂₃₄₅₆₇₈₉'.includes(c)?14:23),0);
 const leftSource=95+width(a),rightSource=350+width(b),leftTarget=95+width(group(a,cb)),rightTarget=350+width(group(b,ca));
 const number=(n,x1,x2,color)=>`<text x="${play&&!moving?x2:x1}" y="${play&&!moving?180:66}" fill="${color}" font-size="27" font-weight="900">${n}${an('x',`${x1};${(x1+x2)/2};${x2}`)}${an('y','66;115;180')}</text>`;
 const sign=(x,txt)=>g==='hn'?'':`<text x="${x}" y="66" font-size="24" fill="var(--muted)" opacity="${play&&!moving?0:1}">${txt}${an('opacity','1;0','0.3s','0.4s')}</text>`;
 return `<svg viewBox="0 0 560 300" style="width:100%;max-width:650px;display:block;margin:auto" role="img" aria-label="Cruce de valores absolutos: ${a}, ${ca}; ${b}, ${cb}. El ${ca} pasa al subíndice de ${b} y el ${cb} al de ${a}. Resultado: ${result}.">
 <text x="280" y="24" text-anchor="middle" font-size="16" fill="var(--muted)">${g==='hn'?'valències de combinación':'càrregues: tomamos sus valores absolutos'}</text>
 <g font-size="38" font-weight="800" fill="var(--ink)"><text x="95" y="90">${a}</text><text x="350" y="90">${b}</text></g>
 <path d="M${leftSource} 96 Q280 105 ${rightTarget} 164" fill="none" stroke="var(--pink)" stroke-width="2" stroke-dasharray="5 5"/><path d="M${rightSource} 96 Q280 140 ${leftTarget} 164" fill="none" stroke="var(--blue)" stroke-width="2" stroke-dasharray="5 5"/>
 <g font-size="38" font-weight="800" fill="var(--ink)"><text x="95" y="170">${group(a,cb)}</text><text x="350" y="170">${group(b,ca)}</text></g>
 ${number(ca,leftSource,rightTarget,'var(--pink)')}${number(cb,rightSource,leftTarget,'var(--blue)')}${sign(leftSource+28,'+')}${sign(rightSource+28,'−')}
 <text x="280" y="222" text-anchor="middle" font-size="15" fill="var(--muted)">El valor de cada càrrega pasa al subíndice del otro element o grup.</text>
 <g opacity="${play&&!moving?1:0}">${an('opacity','0;1','0.3s','2.8s')}<text x="280" y="262" text-anchor="middle" font-size="32" font-weight="900" fill="var(--violet)">${result}</text><text x="280" y="288" text-anchor="middle" font-size="14" fill="var(--muted)">Se omite el subíndice 1; los grups poliatómicos se conservan completos.</text></g></svg>`;
}
function animateCross(){const el=$('cross');el.innerHTML=crossDiagram(tab,true)}
function groupChecks(prefix,selected=CHEM.map(g=>g[0])){return `<div class="checks">${CHEM.map(g=>`<label><input type="checkbox" name="${prefix}g" value="${g[0]}" ${selected.includes(g[0])?'checked':''}> ${g[1]}</label>`).join('')}</div><div class="row"><button class="small" onclick="setGroups('${prefix}',true)">Mezcla de todos</button><button class="small" onclick="setGroups('${prefix}',false)">Desmarcar todos</button></div>`}
function setGroups(prefix,value){document.querySelectorAll(`input[name="${prefix}g"]`).forEach(x=>x.checked=value)}
function selectedGroups(prefix){return [...document.querySelectorAll(`input[name="${prefix}g"]:checked`)].map(x=>x.value)}
function nomOptions(){return '<option value="any">La nomenclatura pròpia de cada família</option><option value="stock">Nomenclatura Stock</option><option value="trad">Tradicional catalana</option><option value="pref">Sistemàtica amb prefixos</option><option value="common">Noms habituals</option>'}
let chosenGroups=CHEM.map(g=>g[0]);function practiceGroup(g){chosenGroups=[g];session=null;go('practice')}
function practice(){if(session){renderExercise();return} $('main').innerHTML=`<div class="lab-head">${mascot(0)}<div><div class="eyebrow">L’espai de pràctica de química</div><h1>Practiquem!</h1><p>Tria les famílies i el nivell. Cada repte t’indica quina nomenclatura has d’utilitzar.</p></div></div><section class="card"><h2>Prepara el teu entrenament</h2><label>Famílies</label>${groupChecks('p',chosenGroups)}<div class="settings" style="margin-top:20px"><label>Mode<select id="pMode" aria-label="Mode"><option value="mixed">Mixt</option><option value="name">Anomenar: fórmula → nom</option><option value="formula">Formular: nom → fórmula</option></select></label><label>Nomenclatura<select id="pNom" aria-label="Nomenclatura">${nomOptions()}</select></label><label>Nivell<select id="pLevel" aria-label="Nivell"><option value="0">Bàsic</option><option value="1">Ampliat (inclou bàsic)</option></select></label><label>exercicis<select id="pCount" aria-label="exercicis"><option>10</option><option>20</option><option value="0">sense límite</option></select></label></div><p id="pError" class="error" role="status"></p><div class="row"><button class="primary" onclick="startPractice()">Comença la pràctica →</button><button onclick="startReview()" ${progress.errors.length?'':'disabled'}>Repassa els meus errors (${progress.errors.length})</button></div></section>${foot()}`}
function pool(groups,level,nom){return BANK.filter(c=>groups.includes(c.g)&&c.level<=level&&(nom==='any'?!!c.n[methodFor(c)]:nom===methodFor(c)&&!!c.n[nom]))}
function rng(seed){let h=2166136261;for(const c of String(seed))h=Math.imul(h^c.charCodeAt(0),16777619);return()=>{h+=0x6D2B79F5;let t=h;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296}}
function shuffle(a,r=Math.random){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function question(c,mode,nom,r=Math.random){const own=methodFor(c);return {id:c.id,mode:mode==='mixed'?(r()<.5?'name':'formula'):mode,nom:nom==='any'?own:nom}}
function startPractice(){let groups=selectedGroups('p');let available=pool(groups,+$('pLevel').value,$('pNom').value);if(!available.length){$('pError').textContent='No hi ha compostos amb aquesta combinació. Tria una altra nomenclatura, més grups o el nivell ampliat.';return}chosenGroups=groups;reviewMode=false;const mode=$('pMode').value,nom=$('pNom').value;session={pool:available.map(c=>c.id),queue:shuffle(available).map(c=>question(c,mode,nom)),mode,nom,limit:+$('pCount').value,index:0,score:0,streak:0,best:0,stars:0,right:0,errors:[],groups:{},hint:false,answered:false};renderExercise()}
function startReview(){let qs=progress.errors.filter(q=>BANK[q.id]&&BANK[q.id].n[q.nom]);if(!qs.length)return;reviewMode=true;session={pool:qs.map(q=>q.id),queue:shuffle(qs),limit:qs.length,index:0,score:0,streak:0,best:0,stars:0,right:0,errors:[],groups:{},hint:false,answered:false};renderExercise()}
function current(){return session.queue[session.index%session.queue.length]}
function promptText(q,html=true){let c=BANK[q.id];if(q.mode==='name')return `Anomena amb ${NOM[q.nom].toLowerCase()}: ${html?form(c.f):pretty(c.f)}`;return `Formula a partir de ${NOM[q.nom].toLowerCase()}: ${html?esc(c.n[q.nom][0]):c.n[q.nom][0]}${c.charge?' (inclou la càrrega)':''}`}
function renderExercise(){const q=current(),c=BANK[q.id];$('main').innerHTML=`<div class="row between"><div><div class="eyebrow">${title(c.g)} · ${reviewMode?'Repàs d’errors':'Missió en curs'}</div><h1>Repte ${session.index+1}${session.limit?' de '+session.limit:''}</h1></div><button onclick="finishPractice()">Acaba i consulta el resum</button></div><div class="stats"><div class="stat">Punts <b id="liveScore">${session.score}</b></div><div class="stat">🔥 Ratxa <b id="liveStreak">${session.streak}</b></div><div class="stat">⭐ <b id="liveStars">${session.stars}</b></div></div>${session.limit?`<div class="progressbar" role="progressbar" aria-label="Progrés" aria-valuemin="0" aria-valuemax="${session.limit}" aria-valuenow="${session.index}"><i style="width:${100*session.index/session.limit}%"></i></div>`:''}<section class="card exercise" id="exercise"><div class="lab-head" id="reaction">${mascot(0)}<div><span class="tag">${q.mode==='name'?'fórmula → nom':'Nom → fórmula'}</span><h2>${promptText(q)}</h2></div></div><label for="answer">La teva resposta</label><input class="answer" id="answer" autocomplete="off" spellcheck="false" placeholder="${q.mode==='name'?'Escriu el nom…':'Exemple: Fe(OH)₃ o Fe(OH)3'}"><p class="notice">${q.mode==='formula'?'Pots escriure amb el teclat habitual o amb el teclat químic. La fórmula distingeix majúscules, parèntesis i subíndexs.':'S’accepten accents omesos i el prefix mono- opcional quan la resta del nom és correcta.'}</p>${q.mode==='formula'?keyboard():''}<div class="row"><button class="primary" id="checkBtn" onclick="checkAnswer()">Comprova</button><button id="hintBtn" onclick="hint()">💡 pista (−1 estrella)</button><button id="nextBtn" onclick="nextQuestion()" hidden>Següent →</button></div><div id="feedback" role="status" aria-live="polite"></div></section>`;$('answer').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();session.answered?nextQuestion():checkAnswer()}};$('answer').focus()}
function keyboard(){return `<div class="keyboard" role="group" aria-label="Teclat químic">${['H','O','N','S','C','Na','Cl','Fe','Ca','Al','Cu','P','Mg','K','Zn','Ba','Ag','Sn','Pb','Cr','Mn','B','Si','As','Sb','F','Br','I','Se','Te','V','Ti','Sc','Pd','Pt','Rb','Cs','Li','Fr','Sr','Cd','Ra','Co','Ni','Hg','Au','Ge','Bi',...Array.from({length:10},(_,i)=>String(i)),'(',')','+','−','CN⁻','NH₄⁺','SeO₄²⁻','(aq)'].map(k=>`<button type="button" class="small" onmousedown="event.preventDefault()" onclick="key('${k}')">${/^\\d$/.test(k)?subdigits[k]:k}</button>`).join('')}<button id="supBtn" class="small ${superMode?'on':''}" aria-pressed="${superMode}" onclick="toggleSuper()">xⁿ Superíndex</button><button class="small" onclick="backspace()">⌫ Esborra</button></div>`}
function insert(s){let a=$('answer');if(a.disabled)return;let i=a.selectionStart,j=a.selectionEnd;a.setRangeText(s,i,j,'end');a.focus()}
function key(k){if(/^\d$/.test(k))k=(superMode?supdigits:subdigits)[k];else if(k==='+')k='⁺';else if(k==='−')k='⁻';insert(k)}
function toggleSuper(){superMode=!superMode;$('supBtn').classList.toggle('on',superMode);$('supBtn').setAttribute('aria-pressed',superMode);$('answer').focus()}
function backspace(){let a=$('answer');if(a.disabled)return;let i=a.selectionStart,j=a.selectionEnd;if(i===j)i=Math.max(0,i-1);a.setRangeText('',i,j,'end');a.focus()}
function normName(s){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹]/g,d=>String(supdigits.indexOf(d))).replaceAll('⁺','+').replaceAll('⁻','−').replace(/[−–—]/g,'-').replace(/\^/g,'').replace(/\(?([1-9][0-9]*[+-])\)?/g,'($1)').replace(/\bion\s*/g,'').replace(/^mon(?=oxid)/,'').replace(/[\s-]/g,'').replace(/[\[\]]/g,c=>c==='['?'(':')')}
function canonicalFormula(raw){let s=String(raw).trim().replace(/\s+(\d*[+−-])$/,'^$1').replace(/\s/g,'').replace(/[−⁻]/g,'-').replaceAll('⁺','+');let idx=s.search(/[⁰¹²³⁴⁵⁶⁷⁸⁹]/);if(idx>=0&&!s.includes('^'))s=s.slice(0,idx)+'^'+s.slice(idx);s=s.replace(/[₀₁₂₃₄₅₆₇₈₉]/g,d=>String(subdigits.indexOf(d))).replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹]/g,d=>String(supdigits.indexOf(d)));if(!s.includes('^')&&/[+-]$/.test(s)){let m=s.match(/^([A-Z][a-z]?)(\d+)([+-])$/);if(m)s=m[1]+'^'+m[2]+m[3];else s=s.slice(0,-1)+'^'+s.slice(-1)}return s.replace(/\^1([+-])$/,'^$1')}
function correct(q,value){let c=BANK[q.id];return q.mode==='formula'?canonicalFormula(value)===canonicalFormula(c.f):c.n[q.nom].some(n=>normName(n)===normName(value))}
function diagnose(c,value,q){if(q.mode==='name'){if(/\([ivx]+\)/i.test(value)&&c.n.stock)return 'Comprova l’estat d’oxidació indicat amb nombres romans. '+c.note;if(/\(\d[+−-]\)/.test(value)&&!c.n.charge)return 'aquí no s’aplica el nom de càrrega d’un metall. Fes servir '+NOM[q.nom].toLowerCase()+'.';return 'Revisa la terminació i els prefixos del nom. '+c.note}let a=canonicalFormula(value);if(c.f.replace(/\(aq\)$/i,'').includes('(')&&!a.includes('('))return 'Falten parèntesis: el subíndex ha de multiplicar tot el grup. '+c.note;if(c.charge&&!a.includes('^'))return 'Falta la càrrega de l’ió en superíndex.';try{let p=parseFormula(a),target=parseFormula(c.f);let ks=Object.keys(target.atoms);let ratios=ks.map(k=>(p.atoms[k]||0)/target.atoms[k]);if(!c.charge&&Object.keys(p.atoms).length===ks.length&&ratios.every(r=>r===ratios[0])&&ratios[0]>1)return 'Cal simplificar els subíndexs a la proporció mínima.'}catch(e){}if(c.g==='pe')return 'conserva el grup O₂²⁻: no simplifiques la pareja de oxígenos.';return 'Revisa els símbols, los subíndices y la compensación de càrregues. '+c.note}
function answerList(c){const rows=Object.entries(c.n).filter(([k,v])=>NOM[k]&&Array.isArray(v)&&v.length).map(([k,v])=>`<p><b>${NOM[k]}:</b> ${v.map(esc).join(' / ')}</p>`).join('');return `<div class="solution"><h3>Solució correcta</h3><p><b>Fórmula:</b> ${form(c.f)}</p>${rows}</div>`}
function hint(){if(session.answered||session.hint)return;session.hint=true;$('hintBtn').disabled=true;$('feedback').innerHTML=`<div class="feedback"><b>💡 La Leire et dona una pista:</b> ${esc(BANK[current().id].note)}<p class="notice">Aquest repte pot donar com a màxim 2 estrelles.</p></div>`}
function celebrate(){if(prefs.reduce||matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<25;i++){let e=document.createElement('i');e.className='confetti';e.style.left=Math.random()*100+'vw';e.style.background=i%2?'var(--gold)':'var(--blue)';e.style.animationDelay=Math.random()*.25+'s';document.body.append(e);setTimeout(()=>e.remove(),1800)}}
function checkAnswer(){if(!session||session.answered)return;let value=$('answer').value;if(!value.trim()){$('feedback').textContent='Escriu una resposta abans de comprovar-la.';return}let q=current(),c=BANK[q.id],ok=correct(q,value);session.answered=true;session.right+=+ok;session.streak=ok?session.streak+1:0;session.best=Math.max(session.best,session.streak);let stars=ok?(session.hint?2:3):0;session.stars+=stars;session.score+=ok?(session.hint?7:10):0;let st=session.groups[c.g]||(session.groups[c.g]={total:0,right:0});st.total++;st.right+=+ok;progress.total++;progress.right+=+ok;progress.stars+=stars;let ps=progress.groups[c.g]||(progress.groups[c.g]={total:0,right:0});ps.total++;ps.right+=+ok;let same=x=>x.id===q.id&&x.nom===q.nom&&x.mode===q.mode;if(ok)progress.errors=progress.errors.filter(x=>!same(x));else{session.errors.push(q);if(!progress.errors.some(same))progress.errors.push(q)}save('progress',progress);$('liveScore').textContent=session.score;$('liveStreak').textContent=session.streak;$('liveStars').textContent=session.stars;$('exercise').classList.add(ok?'happy':'sad');$('reaction').classList.add(ok?'happy':'sad');$('answer').disabled=true;$('checkBtn').disabled=true;$('hintBtn').disabled=true;$('nextBtn').hidden=false;$('feedback').innerHTML=`<div class="feedback ${ok?'':'bad'}"><h3>${ok?'😊 Reacció perfecta!':'🥲 Gairebé! Aquest error t’ajuda a aprendre.'}</h3><p>${ok?'Has guanyat '+stars+' estrelles.':esc(diagnose(c,value,q))}</p>${answerList(c)}</div>`;if(ok)celebrate();$('nextBtn').focus()}
function nextQuestion(){if(!session?.answered)return;session.index++;session.answered=false;session.hint=false;if(session.limit&&session.index>=session.limit){finishPractice();return}if(session.index>=session.queue.length&&!reviewMode){session.queue.push(...shuffle(session.pool).map(id=>question(BANK[id],session.mode,session.nom)))}renderExercise()}
function finishPractice(){if(!session)return;const s=session,n=s.index+(s.answered?1:0),groups=Object.entries(s.groups).sort((a,b)=>a[1].right/a[1].total-b[1].right/b[1].total);session=null;$('main').innerHTML=`<div class="hero"><div><div class="eyebrow">Missió completada</div><h1>La teva química continua progressant.</h1><p>${s.right} encerts de ${n} respostes · ${s.score} punts · ⭐ ${s.stars} estrelles · millor ratxa: ${s.best}.</p><div class="row"><button class="primary" onclick="practice()">Nova missió</button><button onclick="startReview()" ${progress.errors.length?'':'disabled'}>Repassa els meus errors (${progress.errors.length})</button></div></div><div class="hero-art">${mascot(0)}</div></div><section class="card"><h2>Com continuar</h2>${groups.length?table(['Família (primer les que costen més)','Aciertos','Repàs'],groups.map(([g,v])=>[title(g),`${v.right}/${v.total} · ${Math.round(100*v.right/v.total)}%`,`<button class="small" onclick="go('${g}')">Consulta la teoria</button>`])):'Encara no has respost cap exercici.'}</section>${foot()}`}
function teacher(){if(!unlocked){$('main').innerHTML=`<div class="lab-head">${mascot(3)}<div><div class="eyebrow">Espai del professorat</div><h1>Hola!</h1><p>Introdueix el codi per preparar col·leccions.</p></div></div><section class="card" style="max-width:500px"><form id="unlock"><label>Codi d’accés<input id="code" type="password" inputmode="numeric" autocomplete="off" required></label><p id="codeError" role="status"></p><button class="primary">Obre l’espai docent 🔓</button></form><p class="notice">És un bloqueig didàctic del navegador; no protegeix dades sensibles. Es demana una vegada durant aquesta sessió de l’aplicació.</p></section>`;$('unlock').onsubmit=e=>{e.preventDefault();if($('code').value==='4545'){unlocked=true;try{sessionStorage.setItem('leirelab.teacher','4545')}catch(e){}teacher()}else{$('codeError').textContent='Aquest codi no obre l’espai docent. Torna-ho a provar.';$('code').select()}};return}
let saved=read('collections',[]);if(!Array.isArray(saved))saved=[];$('main').innerHTML=`<div class="lab-head">${mascot(3)}<div><div class="eyebrow">Espai docent desbloquejat</div><h1>Una col·lecció a la teva mida.</h1><p>10 per anomenar + 10 per formular. Sense fórmules repetides entre apartats ni versions.</p></div></div><section class="card"><div class="settings"><label>Títol de la col·lecció<input id="tTitle" value="Repte de formulació inorgánica"></label><label>Llavor reproduïble<input id="tSeed" value="LEIRE-01"></label><label>Nivell<select id="tLevel" aria-label="Nivell"><option value="0">Bàsic</option><option value="1">Ampliat (inclou bàsic)</option></select></label></div><h3>Famílies</h3>${groupChecks('t')}<h3>Nomenclatures permeses</h3><div class="checks">${Object.entries(NOM).map(([k,v])=>`<label><input type="checkbox" name="tn" value="${k}" checked> ${v}</label>`).join('')}</div><p class="notice">cada exercici té una nomenclatura concreta compatible amb el compost. Si el filtre no aplega 20 fórmules diferents (40 per a A/B), s’indicarà abans de generar.</p><div class="row"><label><input type="checkbox" id="tSolutions" checked> Inclou les solucions en pàgines separades</label><label><input type="checkbox" id="tAB"> Versions A i B diferents</label></div><p id="tError" class="error" role="status"></p><button class="primary" onclick="generateCollection()">⚗️ Genera-ho tot / torna-ho a generar</button></section><section class="card"><h2>Les meves col·leccions</h2><div class="row"><label>Nom per desar<input id="saveName" placeholder="Ej.: Control òxids 3.º B"></label><button onclick="saveCollection()">Desa la col·lecció actual</button></div><p id="saveStatus" role="status"></p><div id="saved" class="saved-list">${saved.map((s,i)=>`<button class="small" onclick="loadCollection(${i})">📂 ${esc(s.name)}</button>`).join('')||'<p class="notice">Todavía no hay colecciones guardadas.</p>'}</div></section><div id="collectionView"></div>${foot()}`;if(collection){applyCollectionSettings();renderCollection()}}
function tNoms(){return [...document.querySelectorAll('input[name="tn"]:checked')].map(x=>x.value)}
function generateCollection(){let config={groups:selectedGroups('t'),noms:tNoms(),level:+$('tLevel').value,seed:$('tSeed').value||'ERLEN',title:$('tTitle').value||'formulació inorgánica',solutions:$('tSolutions').checked,ab:$('tAB').checked};const candidates=BANK.filter(c=>config.groups.includes(c.g)&&c.level<=config.level&&config.noms.some(n=>c.n[n]));let need=config.ab?40:20;if(candidates.length<need){$('tError').textContent=`Amb aquests filtres hi ha ${candidates.length} fórmules diferents i se’n necessiten ${need}. Afegeix famílies, activa el nivell ampliat o desactiva A/B.`;return}const random=rng(config.seed),chosen=shuffle(candidates,random).slice(0,need);collection={config,revision:0,versions:[]};for(let v=0;v<(config.ab?2:1);v++)collection.versions.push(chosen.slice(v*20,v*20+20).map((c,i)=>{let ns=config.noms.filter(n=>c.n[n]);return question(c,i<10?'name':'formula',ns[Math.floor(random()*ns.length)],random)}));$('tError').textContent='';renderCollection()}
function applyCollectionSettings(){const c=collection.config;$('tTitle').value=c.title;$('tSeed').value=c.seed;$('tLevel').value=c.level;$('tAB').checked=c.ab;$('tSolutions').checked=c.solutions;document.querySelectorAll('input[name="tg"]').forEach(e=>e.checked=c.groups.includes(e.value));document.querySelectorAll('input[name="tn"]').forEach(e=>e.checked=c.noms.includes(e.value))}
function syncCollection(){if(!collection)return;collection.config.title=$('tTitle').value||'formulació inorgánica';collection.config.solutions=$('tSolutions').checked}
function regen(v,i){syncCollection();let used=new Set(collection.versions.flat().map(q=>q.id));let list=BANK.filter(c=>!used.has(c.id)&&collection.config.groups.includes(c.g)&&c.level<=collection.config.level&&collection.config.noms.some(n=>c.n[n]));if(!list.length){$('tError').textContent='No queden fórmules disponibles amb aquest filtre per substituir l’exercici sense repetir-ne cap.';return}const r=rng(collection.config.seed+'-cambio-'+(++collection.revision)),c=list[Math.floor(r()*list.length)],ns=collection.config.noms.filter(n=>c.n[n]);collection.versions[v][i]=question(c,i<10?'name':'formula',ns[Math.floor(r()*ns.length)],r);renderCollection()}
function sheetHTML(qs,v,answers=false){const name=collection.config.ab?' · Versió '+String.fromCharCode(65+v):'';return `<section class="sheet"><h2>${esc(collection.config.title)}${name}${answers?' · Solucions':''}</h2><p class="notice">Llavor: ${esc(collection.config.seed)} · ${collection.config.level?'Ampliat':'Bàsic'}${collection.revision?' · Canvis: '+collection.revision:''}</p>${answers?'':`<div class="headfields">Nom: ___________________________________<br>Curs: ______________ Data: ______________</div>`}${['Anomena','Formula'].map((label,part)=>`<h3>${part+1}. ${label} · 10 exercicis</h3><ol start="${part*10+1}">${qs.slice(part*10,part*10+10).map((q,j)=>{let c=BANK[q.id],idx=part*10+j;return `<li>${answers?`${form(c.f)} → ${c.n[q.nom].map(esc).join(' / ')} <span class="notice">(${NOM[q.nom]})</span>`:`${promptText(q)}<button class="small no-print" onclick="regen(${v},${idx})" aria-label="Torna a generar l’exercici ${idx+1}">↻</button>`}</li>`}).join('')}</ol>`).join('')}</section>`}
function renderCollection(){if(!$('collectionView')||!collection)return;syncCollection();$('collectionView').innerHTML=`<section class="card"><h2>Previsualització</h2><div class="row"><button class="primary" onclick="downloadPDF()">↓ Baixa el PDF A4</button><button onclick="printCollection()">🖨️ Imprimeix / desa com a PDF</button></div><p id="pdfStatus" class="notice" role="status">El PDF utilitza texto vectorial y subíndices. La impresión del navegador funciona també sense conexión.</p></section>`+collection.versions.map((qs,v)=>sheetHTML(qs,v)).join('')+(collection.config.solutions?collection.versions.map((qs,v)=>sheetHTML(qs,v,true)).join(''):'')}
function printCollection(){if(!collection)return;syncCollection();$('printArea').innerHTML=collection.versions.map((qs,v)=>sheetHTML(qs,v)).join('')+(collection.config.solutions?collection.versions.map((qs,v)=>sheetHTML(qs,v,true)).join(''):'');window.print()}
function saveCollection(){if(!collection){$('saveStatus').textContent='Genera primer una col·lecció.';return}syncCollection();let name=$('saveName').value.trim();if(!name){$('saveStatus').textContent='Posa un nom a la col·lecció.';return}let list=read('collections',[]);if(!Array.isArray(list))list=[];let entry={name,data:JSON.parse(JSON.stringify(collection))},idx=list.findIndex(x=>x.name===name);if(idx>=0)list[idx]=entry;else list.push(entry);const ok=save('collections',list);$('saveStatus').textContent=ok?'Col·lecció desada.':'No s’ha pogut desar en aquest navegador. Pots imprimir-la o baixar el PDF.';if(ok)$('saved').innerHTML=list.map((s,i)=>`<button class="small" onclick="loadCollection(${i})">📂 ${esc(s.name)}</button>`).join('')}
function loadCollection(i){const saved=read('collections',[]);const x=Array.isArray(saved)?saved[i]:null;const validQuestion=q=>q&&Number.isInteger(q.id)&&BANK[q.id]&&(q.mode==='formula'||(q.mode==='name'&&typeof q.nom==='string'&&Array.isArray(BANK[q.id].n[q.nom])));const valid=!!(x&&typeof x==='object'&&typeof x.name==='string'&&x.data&&typeof x.data==='object'&&Array.isArray(x.data.versions)&&x.data.versions.length>=1&&x.data.versions.length<=2&&x.data.versions.every(v=>Array.isArray(v)&&v.length===20&&v.every(validQuestion))&&x.data.config&&typeof x.data.config==='object');if(!valid){$('saveStatus').textContent='Aquesta col·lecció no és compatible o està malmesa.';return}collection=JSON.parse(JSON.stringify(x.data));applyCollectionSettings();renderCollection();$('saveStatus').textContent='Col·lecció carregada: '+x.name}
function downloadPDF(){if(!collection)return;syncCollection();if(!window.jspdf){$('pdfStatus').textContent='La biblioteca PDF no s’ha carregat. Fes servir «Imprimeix / desa com a PDF», que funciona sense connexió.';return}try{const doc=new window.jspdf.jsPDF({unit:'mm',format:'a4'});let first=true;const clean=s=>s.replace(/[−–]/g,'-').replaceAll('→',' > ');
 function page(v,sol){if(!first)doc.addPage();first=false;doc.setTextColor(25);doc.setFont('helvetica','bold');doc.setFontSize(17);let heading=collection.config.title+(collection.config.ab?' - Versió '+String.fromCharCode(65+v):'')+(sol?' - Solucions':'');let lines=doc.splitTextToSize(clean(heading),175);doc.text(lines,17,21);let y=24+lines.length*7;doc.setFont('helvetica','normal');doc.setFontSize(10);doc.text(clean('Llavor: '+collection.config.seed+' | '+(collection.config.level?'Ampliat':'Bàsic')),17,y);y+=9;if(!sol){doc.text('Nom: __________________________________________',17,y);y+=8;doc.text('Curs: __________________     Data: __________________',17,y);y+=12}return y}
 function text(s,x,y,w=175,size=10){doc.setFontSize(size);let lines=doc.splitTextToSize(clean(s),w);doc.text(lines,x,y);return y+lines.length*5}
 // Formulas are drawn character-by-character with true baseline shifts; no unsupported Unicode subscripts in standard PDF fonts.
 function pdfFormula(raw,x,y,size=12){let [body,charge]=raw.split('^');for(let ch of body){let isDigit=/\d/.test(ch);doc.setFontSize(isDigit?size*.72:size);doc.text(ch,x,y+(isDigit?1.2:0));x+=doc.getTextWidth(ch)}if(charge){doc.setFontSize(size*.72);for(let ch of charge){if(ch==='-'){doc.setLineWidth(.23);doc.line(x,y-2.5,x+1.7,y-2.5);x+=2}else{doc.text(ch,x,y-1.8);x+=doc.getTextWidth(ch)}}}doc.setFontSize(size);return x}
 collection.versions.forEach((qs,v)=>{let y=page(v,false);for(let part=0;part<2;part++){doc.setFont('helvetica','bold');doc.setFontSize(13);doc.text(part?'2. Formula (10 exercicis)':'1. Anomena (10 exercicis)',17,y);y+=9;doc.setFont('helvetica','normal');qs.slice(part*10,part*10+10).forEach((q,j)=>{let c=BANK[q.id],num=part*10+j+1;if(q.mode==='name'){doc.setFontSize(11);doc.text(num+'.',18,y);pdfFormula(c.f,27,y);doc.setFontSize(8);doc.text(clean(NOM[q.nom]),85,y);doc.setDrawColor(170);doc.line(27,y+4,190,y+4);y+=9}else{y=text(num+'. '+c.n[q.nom][0]+(c.charge?' (inclou càrrega)':''),18,y,172,10);doc.setDrawColor(170);doc.line(27,y+2,190,y+2);y+=6}});y+=6}});
 if(collection.config.solutions)collection.versions.forEach((qs,v)=>{let y=page(v,true);qs.forEach((q,i)=>{let c=BANK[q.id];if(y>255)y=page(v,true);doc.setFont('helvetica','bold');doc.setFontSize(10);doc.text((i+1)+'.',17,y);let end=pdfFormula(c.f,26,y,11);doc.setFont('helvetica','normal');y=text(' = '+c.n[q.nom].join(' / ')+' ['+NOM[q.nom]+']',Math.max(end+3,48),y,190-Math.max(end+3,48),9)+5})});doc.save('LeireLab_'+collection.config.seed.replace(/[^a-z0-9_-]/gi,'_')+'.pdf');$('pdfStatus').textContent='PDF generat. Si el navegador bloqueja la baixada, fes servir l’opció Imprimeix.'}catch(e){console.error(e);$('pdfStatus').textContent='No s’ha pogut generar el PDF. Fes servir «Imprimeix / desa com a PDF».'}}
// REVISAR: «todas neutras» no se aplica a ions. «Simplificadas» significa unidades iónicas mínimas, no reducir fórmules moleculares como H4SiO4 a HSiO.
function gcd(a,b){return b?gcd(b,a%b):a}
function parseFormula(raw){const parts=canonicalFormula(raw).replace(/\(aq\)$/i,'').split('^');if(parts.length>2)throw Error('càrrega duplicada');let body=parts[0],idx=0;function group(end){const atoms={};while(idx<body.length&&body[idx]!==')'){let chunk;if(body[idx]==='('){idx++;chunk=group(true);if(body[idx]!==')')throw Error('parèntesis sense cierre');idx++}else{let m=body.slice(idx).match(/^[A-Z][a-z]?/);if(!m)throw Error('Símbolo inválido en '+raw);idx+=m[0].length;chunk={[m[0]]:1}}let m=body.slice(idx).match(/^\d+/),n=m?+m[0]:1;if(n<1||(m&&m[0][0]==='0'))throw Error('Subíndice inválido');if(m)idx+=m[0].length;for(let [e,v] of Object.entries(chunk))atoms[e]=(atoms[e]||0)+v*n}if(!end&&idx!==body.length)throw Error('Cierre sobrante');return atoms}const atoms=group(false);let charge=0;if(parts[1]){let m=parts[1].match(/^(\d*)([+-])$/);if(!m)throw Error('càrrega inválida');charge=(m[1]?+m[1]:1)*(m[2]==='+'?1:-1)}return{atoms,charge}}
function formulaFromCharges(cation,anion,positive,negative,poly=false,peroxide=false){if(!Number.isInteger(positive)||positive<1||!Number.isInteger(negative)||negative<1)throw Error('càrregues no vàlides');if(cation==='Hg'&&positive===1)throw Error('El mercuri(I) forma el catió Hg₂²⁺.');const d=gcd(positive,negative),x=negative/d,y=positive/d;const suffix=n=>n===1?'':String(n);if(peroxide){if(anion!=='O'||negative!==2)throw Error('El peròxid requereix el grup O₂²⁻.');return cation+suffix(x)+'O2'+suffix(y)}return cation+suffix(x)+(poly&&y>1?'('+anion+')':anion)+suffix(y)}
function generatedFromBank(cation,anion,positive,negative,poly=false,peroxide=false){let formula=formulaFromCharges(cation,anion,positive,negative,poly,peroxide);const result=BANK.find(c=>c.f===formula&&c.ox[cation]===positive);if(!result)throw Error('Aquesta combinació no és al banc verificat.');return result}
function selfTest(){const failures=[];let checks=0;const assert=(condition,message)=>{checks++;if(!condition)failures.push(message)};for(let c of BANK){try{let p=parseFormula(c.f),sum=Object.entries(p.atoms).reduce((a,[el,n])=>a+n*c.ox[el],0);assert(Number.isFinite(sum)&&sum===c.charge,c.f+': suma de estats incorrecta');assert(p.charge===c.charge,c.f+': càrrega escrita incorrecta');if(c.units)assert(gcd(...c.units)===1,c.f+': unidades sense simplificar');if(c.g==='pe')assert(p.atoms.O===2,c.f+': falta pareja peròxid');assert(Object.values(c.n).every(a=>a.length&&a.every(n=>typeof n==='string'&&n.length>2)),c.f+': nom vacío');if(c.n.charge&&c.g!=='io'&&c.g!=='hidden')assert(['ox','hm','sb','oh'].includes(c.g)&&/\([1-9]\+\)/.test(c.n.charge[0]),c.f+': tarjeta de càrrega indebida');if(c.g==='pe')assert(!c.n.charge,c.f+': càrrega en peròxid');if(['oa','op'].includes(c.g))assert(!!c.n.trad&&!!c.n.hyd,c.f+': nomenclatura de oxácido incompleta');if(c.g==='oh'&&p.atoms.O>1)assert(c.f.includes('(OH)'),c.f+': parèntesis OH');for(let ns of Object.values(c.n))for(let n of ns)assert(!n.includes('undefined'),c.f+': nom inválido');if(false&&['ox','hm','sb','oh'].includes(c.g)&&c.n.pref){const order=Object.keys(p.atoms),first=order[0],last=c.g==='oh'?'OH':order[1],count=last==='OH'?p.atoms.O:p.atoms[last];const roots={O:'oxido',H:'hidrur',Cl:'clorur',S:'sulfur',F:'fluorur',OH:'hidroxido'},prefix=['','','di','tri','tetra','penta','hexa','hepta'];assert(normName(c.n.pref[0]).startsWith(prefix[count]+roots[last]),c.f+': prefix no coincide con el anió');if(c.n.stock){const roman=c.n.stock[0].match(/\(([IVX]+)\)/);if(roman)assert(({I:1,II:2,III:3,IV:4,V:5,VI:6,VII:7})[roman[1]]===c.ox[first],c.f+': romano no coincide con el estat');}}assert(correct({id:c.id,mode:'formula'},pretty(c.f)),c.f+': format visual no acceptat');for(let k of Object.keys(c.n))assert(correct({id:c.id,mode:'name',nom:k},c.n[k][0]),c.f+': nom propi no acceptat')}catch(e){failures.push(c.f+': '+e.message)}}
const golden=[['Fe2O3','pref','triòxid de diferro'],['Fe2O3','stock','òxid de ferro(III)'],['Fe2O3','charge','òxid de ferro(3+)'],['Na2O2','stock','peròxid de sodi'],['H4P2O7','hyd','tetrahidrogen(heptaoxidodifosfat)'],['Al2(SO4)3','pref','tris(tetraoxidosulfat) de dialumini'],['Ca3(PO4)2','pref','bis(tetraoxidofosfat) de tricalci'],['Ca(HCO3)2','pref','bis[hidrogen(trioxidocarbonat)] de calci']];for(let [f,k,n] of golden){let c=BANK.find(c=>c.f===f);assert(c?.n[k]?.includes(n),'Nom de referencia: '+f)}assert(formulaFromCharges('Fe','O',3,2)==='Fe2O3','Intercanvi Fe/O');assert(formulaFromCharges('Ca','OH',2,1,true)==='Ca(OH)2','Intercanvi Ca/OH');assert(formulaFromCharges('Na','O',1,2,false,true)==='Na2O2','Fórmula de peròxid');assert(canonicalFormula('Fe3+')==='Fe^3+','Càrrega de teclat');assert(canonicalFormula('SO₄²⁻')==='SO4^2-','Càrrega Unicode');assert(!correct({id:BANK.find(c=>c.f==='Ca(OH)2').id,mode:'formula'},'CaOH2'),'Cal exigir parèntesis');assert(!correct({id:BANK.find(c=>c.f==='Fe2O3').id,mode:'formula'},'Fe4O6'),'Cal exigir simplificación');assert(normName('monòxid de carboni')===normName('òxid de carboni'),'El prefix mono és opcional només davant d’òxid');assert(BANK.some(c=>c.g==='ox'&&c.ox['V']===2),'V valència 2 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['V']===3),'V valència 3 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['V']===4),'V valència 4 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['V']===5),'V valència 5 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Ti']===4),'Ti valència 4 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Sc']===3),'Sc valència 3 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Pd']===2),'Pd valència 2 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Pd']===4),'Pd valència 4 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Pt']===2),'Pt valència 2 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Pt']===4),'Pt valència 4 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Rb']===1),'Rb valència 1 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Cs']===1),'Cs valència 1 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Li']===1),'Li valència 1 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Fr']===1),'Fr valència 1 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Sr']===2),'Sr valència 2 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Cd']===2),'Cd valència 2 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Ra']===2),'Ra valència 2 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Co']===2),'Co valència 2 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Co']===3),'Co valència 3 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Ni']===2),'Ni valència 2 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Ni']===3),'Ni valència 3 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Hg']===1),'Hg valència 1 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Hg']===2),'Hg valència 2 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Au']===1),'Au valència 1 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Au']===3),'Au valència 3 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Ge']===2),'Ge valència 2 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Ge']===4),'Ge valència 4 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Bi']===3),'Bi valència 3 disponible');assert(BANK.some(c=>c.g==='ox'&&c.ox['Bi']===5),'Bi valència 5 disponible');assert(BANK.some(c=>c.f==='K2Cr2O7'&&c.g==='sn'),'Dicromat de potassi inclòs');assert(BANK.some(c=>c.f==='Hg2(OH)2'),'Fórmula correcta de l’hidròxid de mercuri(I)');assert(BANK.some(c=>c.f==='Hg2Cl2'),'Fórmula correcta del clorur de mercuri(I)');assert(BANK.some(c=>c.g==='sa'),'Banc de sals àcides disponible');assert(GROUPS.some(g=>g[0]==='sa'),'Apartat de sals àcides visible');let badPeroxide=false;try{formulaFromCharges('Na','O',1,1,false,true)}catch(e){badPeroxide=true}assert(badPeroxide,'Validació de la càrrega del peròxid');const aq=BANK.find(c=>c.f==='HCl(aq)'),gas=BANK.find(c=>c.f==='HCl');
assert(!!aq&&aq.g==='ah'&&correct({id:aq.id,mode:'formula'},'HCl(aq)'),'HCl(aq) es corregeix com a àcid');
assert(!!gas&&correct({id:gas.id,mode:'name',nom:'stock'},"clorur d'hidrogen"),'HCl sense (aq) és clorur d’hidrogen');
assert(!correct({id:aq.id,mode:'formula'},'HCl'),'Cal distingir HCl de HCl(aq)');
assert(BANK.some(c=>c.f==='SiH4'&&c.n.common?.includes('silà')),'Silà disponible');
assert(BANK.some(c=>c.f==='C4H10'&&c.n.common?.includes('butà')),'Butà disponible');
assert(BANK.some(c=>c.f==='NH3'&&c.n.common?.includes('amoníac')),'Amoníac disponible');
assert(BANK.some(c=>c.f==='PH3'&&c.n.common?.includes('fosfà')),'Fosfà disponible');
assert(BANK.some(c=>c.f==='AsH3'&&c.n.common?.includes('arsà')),'Arsà disponible');
assert(BANK.some(c=>c.f==='SbH3'&&c.n.common?.includes('estibà')),'Estibà disponible');
assert(BANK.some(c=>c.f==='NO'&&c.ox.N===2)&&BANK.some(c=>c.f==='NO2'&&c.ox.N===4),'Òxids de nitrogen +2 i +4 disponibles');
assert(BANK.some(c=>c.f==='NH4Cl'&&c.n.stock?.includes('clorur d’amoni')),'Clorur d’amoni disponible');
assert(BANK.some(c=>c.f==='Ti(CN)4'&&c.n.stock?.includes('cianur de titani')),'Cianur de titani disponible');
assert(BANK.some(c=>c.f==='CN^-'&&c.n.trad?.includes('ió cianur')),'Ió cianur disponible');
assert(BANK.some(c=>c.f==='NH4^+'&&c.n.trad?.includes('ió amoni')),'Ió amoni disponible');
assert(BANK.some(c=>c.f==='SeO4^2-'&&c.n.trad?.includes('ió selenat')),'Ió selenat disponible');
assert(pool(['hn'],1,'any').length>=7,'Els set hidrurs no metàl·lics es poden practicar');
assert(pool(['io'],1,'any').some(c=>c.f==='SeO4^2-'),'Els ions es poden practicar');assert(pool(['io'],1,'any').some(c=>c.f==='CN^-'),'L’ió cianur es pot practicar');assert(pool(['io'],1,'any').some(c=>c.f==='NH4^+'),'L’ió amoni es pot practicar');assert(pool(['sb'],1,'any').some(c=>c.f==='NH4Cl'),'El clorur d’amoni es pot practicar');assert(pool(['sb'],1,'any').some(c=>c.f==='Ti(CN)4'),'El cianur de titani es pot practicar');assert(!BANK.some(c=>Object.values(c.n).flat().some(n=>/\bmeta[- ]/i.test(n))),'No queden oxoàcids meta al banc');
const result={compostos:BANK.length,comprovacions:checks,errors:failures};console.group('LeireLab · Autotest químic');console[failures.length?'error':'info'](result);console.groupEnd();return result}
const TEST_RESULT=selfTest();window.LeireLab={BANK,correct,canonicalFormula,parseFormula,formulaFromCharges,generatedFromBank,selfTest,TEST_RESULT};go('home',false);
